/**
 * Runtime helpers for GLB models generated by tools/models (see tools/models/lib.ts).
 *
 * What the GLBs contain and what PlayCanvas 2.23 does with them:
 * - Opaque parts use material "tl_matte" (cloth: "tl_cloth", double-sided). Their colours are
 *   per-vertex COLOR_0 in LINEAR space with a white baseColor. The glTF parser already sets
 *   diffuseVertexColor = true (vertexColorGamma stays false = linear), so nothing is needed.
 *   If you replace materials (e.g. one shared material for batching), keep
 *   `diffuseVertexColor = true` and `vertexColorGamma = false` or the models turn white.
 * - Emissive parts use "tl_glow" / "tl_glow_<strength>" (KHR_materials_unlit + COLOR_0 +
 *   KHR_materials_emissive_strength -> emissiveIntensity). PlayCanvas' unlit import leaves
 *   diffuse = white, so the scene ambient light is ADDED to the glow colour (washes it out).
 *   prepareModelContainer() sets those materials' diffuse to black so glows render exactly.
 *   Flicker at runtime by animating material.emissiveIntensity of the glow materials.
 * - Glow parts are light sources: instantiateModel() turns off their shadow casting.
 * - Camera: toneMapping TONEMAP_ACES + gammaCorrection GAMMA_SRGB (what the gallery shows).
 */
import * as pc from "playcanvas";

export const GLOW_MATERIAL_PREFIX = "tl_glow";

const isGlow = (m: pc.Material | null | undefined): m is pc.StandardMaterial =>
  m instanceof pc.StandardMaterial && m.name.startsWith(GLOW_MATERIAL_PREFIX);

/** Fix up a loaded container once (idempotent). Returns the same resource. */
export function prepareModelContainer(res: pc.ContainerResource): pc.ContainerResource {
  for (const asset of res.materials) {
    const m = asset.resource;
    if (isGlow(m)) {
      m.diffuse.set(0, 0, 0);
      m.update();
    }
  }
  return res;
}

const cache = new Map<string, Promise<pc.ContainerResource>>();

/**
 * Load (once per URL) and prepare a model container. A failed load is not cached: calling again
 * requests the file again (retries after a network hiccup).
 */
export function loadModelContainer(app: pc.AppBase, url: string): Promise<pc.ContainerResource> {
  let p = cache.get(url);
  if (!p) {
    const loading = new Promise<pc.ContainerResource>((resolve, reject) => {
      app.assets.loadFromUrl(url, "container", (err, asset) => {
        if (err || !asset?.resource) {
          if (asset) app.assets.remove(asset); // a later retry registers a fresh asset
          reject(new Error(`model ${url}: ${String(err ?? "no resource")}`));
        } else resolve(prepareModelContainer(asset.resource as pc.ContainerResource));
      });
    });
    loading.catch(() => {
      if (cache.get(url) === loading) cache.delete(url);
    });
    cache.set(url, loading);
    p = loading;
  }
  return p;
}

/**
 * Instantiate a prepared container: render entities with shadows on, except glow parts which
 * neither cast nor receive shadows. Node names from the manifest are entity names
 * (entity.findByName("arm_upper_l")).
 */
export function instantiateModel(res: pc.ContainerResource, castShadows = true): pc.Entity {
  const root = res.instantiateRenderEntity({ castShadows, receiveShadows: true });
  for (const r of root.findComponents("render"))
    for (const mi of r.meshInstances)
      if (isGlow(mi.material)) {
        mi.castShadow = false;
        mi.receiveShadow = false;
      }
  return root;
}

/** Glow materials used under an instantiated model (e.g. to flicker emissiveIntensity). */
export function glowMaterials(root: pc.Entity): pc.StandardMaterial[] {
  const out = new Set<pc.StandardMaterial>();
  for (const r of root.findComponents("render"))
    for (const mi of r.meshInstances) if (isGlow(mi.material)) out.add(mi.material);
  return [...out];
}
